import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // --- ESTADOS DE AUTENTICACIÓN ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // --- ESTADOS DE PANTALLA Y DATOS ---
  const [pantalla, setPantalla] = useState('catalogo');
  const [productos, setProductos] = useState([]); // Datos del Backend

  // Catálogo Maestro (Persistencia local que NO se borra)
  const [catalog, setCatalog] = useState(() => {
    const savedCatalog = localStorage.getItem('master_catalog_paisita');
    return savedCatalog ? JSON.parse(savedCatalog) : [];
  });

  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  // --- Estados de Formulario ---
  const [nombre, setNombre] = useState('');
  const [categoria, setCategoria] = useState('');
  const [imagenUrl, setImagenUrl] = useState('');
  const [precioCosto, setPrecioCosto] = useState('');
  const [impuesto, setImpuesto] = useState('19');
  const [precioVenta, setPrecioVenta] = useState('');
  const [stock, setStock] = useState('');

  // --- EFECTOS ---
  // Sincronizar catálogo maestro a local storage
  useEffect(() => {
    localStorage.setItem('master_catalog_paisita', JSON.stringify(catalog));
  }, [catalog]);

  // Sincronizar ventas
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  // Cargar inventario del servidor
  useEffect(() => {
    if (isLoggedIn) obtenerInventarioBackend();
  }, [isLoggedIn]);

  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) { console.error("Error al sincronizar:", error); }
  };

  // --- FUNCIONES PRINCIPALES ---
  const handleGuardar = async (e) => {
    e.preventDefault();

    // 1. Guardar en Catálogo Maestro (si es nuevo)
    const yaExisteEnCatalog = catalog.find(p => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim());
    if (!yaExisteEnCatalog) {
      const nuevoItem = { nombre, categoria, imagenUrl, precioCosto, precioVenta };
      setCatalog([...catalog, nuevoItem]);
    }

    // 2. Enviar a Backend
    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl,
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("Producto ingresado correctamente.");
        setNombre(''); setCategoria(''); setImagenUrl(''); setPrecioCosto(''); setPrecioVenta(''); setStock('');
        obtenerInventarioBackend();
        setPantalla('catalogo');
      }
    } catch (error) { alert("Error de conexión con el servidor."); }
  };

  const handleBorrarTodo = async () => {
    if (window.confirm("⚠️ ¿Seguro que quieres vaciar el INVENTARIO del servidor? (El catálogo de productos en tu navegador permanecerá guardado)")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', { method: 'DELETE' });
        if (respuesta.ok) {
          setProductos([]);
          setVentasDelDia([]);
          alert("Inventario borrado del servidor.");
        }
      } catch (error) { alert("Error de conexión."); }
    }
  };

  const registrarVenta = (producto) => {
    // ... tu lógica de venta actual ...
    const inventarioActualizado = productos.map((p) => {
      if (p.id === producto.id) return { ...p, stock: p.stock - 1 };
      return p;
    });
    setProductos(inventarioActualizado);
    setVentasDelDia([...ventasDelDia, { ...producto, id: Date.now(), hora: new Date().toLocaleTimeString() }]);
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v);

  // --- RENDERIZADO ---
  if (!isLoggedIn) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', backgroundColor: '#1a1a1a' }}>
        <div style={{ background: '#252525', padding: '2rem', borderRadius: '10px', textAlign: 'center', width: '300px', color: 'white' }}>
          <h2>Login - El Paisita UP</h2>
          <input type="text" placeholder="Usuario" onChange={(e) => setUsername(e.target.value)} style={{ width: '100%', padding: '10px', margin: '10px 0' }} />
          <input type="password" placeholder="Contraseña" onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: '10px', margin: '10px 0' }} />
          <button onClick={() => { if(username === 'admin' && password === '12345') setIsLoggedIn(true); else alert('Datos incorrectos'); }} style={{ width: '100%', padding: '10px', backgroundColor: '#e3cbb3', border: 'none', cursor: 'pointer' }}>Ingresar</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app-layout">
      <header className="app-header">
        <h1>El Paisita UP</h1>
        <nav>
          <button onClick={() => setPantalla('catalogo')}>📦 Inventario</button>
          <button onClick={() => setPantalla('formulario')}>➕ Nuevo</button>
          <button onClick={handleBorrarTodo}>🔥 Limpiar BD</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="grid-catalogo">
            {productos.map((prod) => (
              <div key={prod.id} className="card-producto">
                <div className="card-image-wrapper">
                  {/* SECCIÓN CORREGIDA: Sin onError, si el link falla, verás que no carga */}
                  <img src={prod.imagenUrl} alt={prod.nombre} style={{ width: '100%', height: '200px', objectFit: 'cover' }} />
                </div>
                <h3>{prod.nombre}</h3>
                <p>Precio: {formatearMoneda(prod.precioVenta)}</p>
                <button onClick={() => registrarVenta(prod)}>Vender</button>
              </div>
            ))}
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container">
            <form onSubmit={handleGuardar}>
              <input type="text" placeholder="Nombre" value={nombre} onChange={(e) => setNombre(e.target.value)} required />
              <input type="text" placeholder="URL Imagen (Ej: https://via.placeholder.com/150)" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} required />
              <input type="number" placeholder="Precio Costo" value={precioCosto} onChange={(e) => setPrecioCosto(e.target.value)} required />
              <input type="number" placeholder="Precio Venta" value={precioVenta} onChange={(e) => setPrecioVenta(e.target.value)} required />
              <input type="number" placeholder="Stock" value={stock} onChange={(e) => setStock(e.target.value)} required />
              <button type="submit">Guardar Producto</button>
            </form>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
